import { cookies, headers } from 'next/headers';

function getPreferredLanguage(acceptLanguage: string | null): string {
  if (!acceptLanguage) return 'Not specified';

  // Accept-Language format: "en-US,en;q=0.9,es;q=0.8" - first value is preferred
  const firstLocale = acceptLanguage.split(',')[0]?.trim();
  return firstLocale || 'Not specified';
}

export default async function UserPreferences() {
  const cookieStore = await cookies();
  const headerStore = await headers();

  const theme = cookieStore.get('theme')?.value ?? 'light';
  const acceptLanguage = headerStore.get('accept-language');
  const preferredLanguage = getPreferredLanguage(acceptLanguage);

  return (
    <section className="user-preferences">
      <h2>Current Preferences</h2>
      <dl>
        <dt>Theme</dt>
        <dd>{theme}</dd>
        <dt>Preferred Language</dt>
        <dd>{preferredLanguage}</dd>
      </dl>
    </section>
  );
}

